Translate("ptBR", "city-of-dalaran", {
	title = "Cidade de Dalaran",
	aliases = { "a cidade dos magos" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Cidade de Dalaran se ergue de novo na margem oeste do {red:lordamere-lake}Espelho de Lordaeron{/red}, ao pé das {link:alterac-mountains}Montanhas de Alterac{/link}. Suas torres violeta se elevam sobre muralhas novas e ruas claras, seus bancos e estalagens estão abertos, e seus magos andam outra vez entre mercadores, artesãos e hóspedes de terras distantes. Por anos, a cidade se escondeu atrás de uma grande cúpula de luz enquanto seus magos a reconstruíam. Essa barreira caiu. O mundo pode ver {link:dalaran}Dalaran{/link} de novo, e Dalaran agora precisa responder ao mundo.]=],
		},
		{
			title = "Origens",
			text = [=[A história de {link:dalaran}Dalaran{/link}, a primeira das cidades livres de {link:arathor}Arathor{/link} e lar do {link:kirin-tor}Kirin Tor{/link}, é contada em sua própria crônica. Na {link:third-war}Terceira Guerra{/link}, o {link:scourge}Flagelo{/link} chegou a seus portões e tomou o livro de feitiços de {link:medivh}Medivh{/link}, e {link:archimonde}Archimonde{/link} destruiu a cidade com um único feitiço. Os magos sobreviventes voltaram às ruínas. Ergueram uma vasta cúpula mágica sobre o coração de sua cidade e, atrás dela, puseram-se a trabalhar. Do lado de fora, as patrulhas dos {link:the-wizards-of-ambermill}magos de Dalaran{/link} e seus elementais sujeitados guardavam os arredores arruinados, e poucos que se aproximavam eram bem-vindos.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[O trabalho está feito, ou quase. Ninguém fora do {link:kirin-tor}Kirin Tor{/link} sabe dizer ainda por que a barreira caiu. A cidade está aberta, mas não está em paz. Encantamentos se desviam, construtos arcanos escapam de suas amarras, e energia demoníaca foi sentida em suas ruas. Investigadores do Kirin Tor falam em voz baixa de uma perturbação que piora a cada dia, e receberam ordens de manter os cidadãos calmos. O Kirin Tor agora se conta entre as nações da {link:alliance}Aliança{/link}. A {link:horde}Horda{/link} não é bem-vinda aqui, e os guardas da cidade tratam seu povo como inimigo. Em vez disso, chegaram novos amigos: a {link:high-order}High Order{/link} dos {link:skyborne}Skyborne{/link}, cujos navios skycutter navegam entre {link:dalaran}Dalaran{/link} e a {link:zephras-isle}Zephras Isle{/link} através dos planos.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}O {link:kirin-tor}Kirin Tor{/link}.{/b} Arquimagos, arquivistas, arcanistas e investigadores, os senhores da cidade.
• {b}Os guardas de {link:dalaran}Dalaran{/link}.{/b} Guardas e executores do Kirin Tor, e sentinelas arcanas que vigiam por conta própria.
• {b}Cidadãos e mercadores.{/b} Banqueiros, estalajadeiros, ferreiros, alfaiates, joalheiros e um fabricante de brinquedos, e um orfanato com sua matrona.
• {b}Os {link:skyborne}Skyborne{/link}.{/b} Magos da {link:high-order}High Order{/link}, que chegam ao cais dos skycutters da cidade.
• {b}Visitantes.{/b} Entre eles, um mestre de druidas e um Bem-nascido que veio de longe.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Fundação.{/b} {link:dalaran}Dalaran{/link} foi a primeira cidade de {link:arathor}Arathor{/link} a governar a si mesma, e seus magos fundaram o {link:kirin-tor}Kirin Tor{/link}.
• {b}A Queda.{/b} Na {link:third-war}Terceira Guerra{/link}, a cidade foi destruída.
• {b}A Barreira.{/b} Os magos reconstruíram Dalaran atrás de uma cúpula que mantinha o mundo do lado de fora.
• {b}Os Dias Atuais.{/b} A barreira se foi, e a cidade abriu seus portões a seus aliados.]=],
		},
		{
			title = "Saberes da Cidade",
			text = [=[• Magos de {link:dalaran}Dalaran{/link} agora vigiam as estradas do norte. Em {link:silverpine-forest}Pinhaprata{/link}, dizem que fazem isso desde que a barreira caiu.
• O arquimago {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} escreveu certa vez um tomo sobre as lendas dos trolls Gurubashi. Sua filha, para seu pesar, tornou-se pirata.
• O {link:kirin-tor}Kirin Tor{/link} mantém um portal para a {link:high-order}High Order{/link}, para que seus jovens magos possam chegar a {link:stormwind-city}Ventobravo{/link} e conhecer o regente ali.]=],
		},
	},
})

Translate("ptBR", "the-eventide", {
	title = "The Eventide",
	aliases = { "Eventide" },
	sections = {
		{
			title = "Resumo",
			text = [=[The Eventide é um dos bairros da cidade reconstruída de {link:dalaran}Dalaran{/link}. Como o resto da cidade, foi erguido de novo atrás da grande barreira enquanto o mundo lá fora não podia vê-lo, e só há pouco foi aberto aos visitantes. Suas ruas são novas, e muitas das pessoas que andam por elas também. Nenhuma crônica registra ainda quem mora no Eventide, nem o que os magos construíram ali primeiro. Quem anda por suas ruas encontra uma cidade orgulhosa de sua restauração, e mais inquieta do que gostaria de admitir.]=],
		},
	},
})

Translate("ptBR", "archmage-ansirem-runeweaver", {
