			title = "Resumo",
			text = [=[A Arquimaga Modera é uma das mais antigas integrantes do conselho que governa o {link:kirin-tor}Kirin Tor{/link}. Estava entre os magos que governavam {link:dalaran}Dalaran{/link} nos dias da {link:second-war}Segunda Guerra{/link}. Antes da praga, falou contra {link:kel-thuzad}Kel'Thuzad{/link} quando seu estudo da necromancia veio à luz, e avisou que os métodos dele fariam todos serem condenados. Seu aviso foi ouvido, e ele foi expulso. Ela sobreviveu à queda da cidade e ficou para vê-la se erguer de novo.]=],
		},
		{
			title = "Importância",
			text = [=[Modera é uma memória viva do antigo {link:kirin-tor}Kirin Tor{/link}, e uma voz que estava certa sobre o homem que destruiu {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Sem Registro",
