		},
	},
	bonds = {
		{ id = "archmage-ansirem-runeweaver", name = "Arquimago Ansirem Runeweaver", note = "um colega arquimago" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "ela falou contra ele" },
	},
})

